use std::{fs,path::Path,collections::BTreeMap};use serde_json::{Value,json};use sha2::{Sha256,Digest};const R:&str="/home/ubuntu/src/zopro-perf-work/scalar-layout215";fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn med(mut x:Vec<f64>)->f64{x.sort_by(f64::total_cmp);x[x.len()/2]}
fn main(){let smoke_only=std::env::args().nth(1).as_deref()==Some("smoke");let r=Path::new(R);let base=Path::new("/home/ubuntu/src/zopro-perf-work/group-pmu214/source");let old=read(base.join(".xtask/source-pins.json"));let mut retained=0;let mut changed=vec![];for(p,h)in old.as_object().unwrap(){let rel=p.strip_prefix(&format!("{}/",base.display())).unwrap();if hash(r.join("source").join(rel))==h.as_str().unwrap(){retained+=1;}else{changed.push(rel);}}assert_eq!(retained,178);assert_eq!(changed,vec!["crates/zopro-core/src/boolean_phase_trace.rs","crates/zopro-core/src/fused_canonical_gather.rs","crates/zopro-core/src/lib.rs","crates/zopro-core/src/msm_affine/workspace.rs"]);let original=fs::read(base.join("crates/zopro-core/src/fused_canonical_gather.rs")).unwrap();let new=fs::read(r.join("source/crates/zopro-core/src/fused_canonical_gather.rs")).unwrap();assert!(new.starts_with(&original));
let jobs=read(r.join("jobs.json"));let mut count=0;let mut processes=0;let mut layout_counts=BTreeMap::<usize,usize>::new();for j in jobs.as_array().unwrap(){let smoke=j["smoke"]==true;if smoke_only&&!smoke{continue;}let name=j["name"].as_str().unwrap();let d=r.join(format!("{}-run/{name}",if smoke{"smoke"}else{"main"}));let e=read(d.join("exit.json"));assert_eq!(e["returncode"],0);assert_eq!(hash(d.join("stdout.log")),e["stdout_sha256"]);let out=fs::read_to_string(d.join("stdout.log")).unwrap();let want=if j["aligned32"]==true{32}else{16};let mut n=0;for l in out.lines().filter_map(|l|l.strip_prefix("PHASE ")){let v:Value=serde_json::from_str(l).unwrap();let layout:Vec<usize>=serde_json::from_value(v["scalar_layout"].clone()).unwrap();assert_eq!(layout,vec![want,30089,56]);*layout_counts.entry(want).or_default()+=1;count+=1;n+=1;}assert_eq!(n,j["rounds"].as_u64().unwrap());let s:Value=serde_json::from_str(out.lines().find_map(|l|l.strip_prefix("SUMMARY ")).unwrap()).unwrap();assert_eq!(s["boolean_routes"],json!([0,0,0,0]));assert_eq!(s["boolean_positions"],0);processes+=1;}
let mut comparisons=vec![];let mut mechanism=false;let mut sdk_selected=false;if !smoke_only{assert_eq!(count,3016);assert_eq!(processes,16);let rows=read(r.join("main-rows.json"));let pmu=read(r.join("pmu-result.json"));let ready=pmu["ready_to_interpret"]==true;let mut cycle_ratios=vec![];for p in pmu["paired_blocks"].as_array().unwrap(){cycle_ratios.push(p["ratios"]["cycles"].as_f64().unwrap());}mechanism=ready&&cycle_ratios.iter().all(|&v|v<1.);
for trace in[false,true]{let get=|b:usize,l32:bool|rows.as_array().unwrap().iter().find(|r|r["job"]["smoke"]==false&&r["job"]["trace"]==trace&&r["job"]["aligned32"]==l32&&r["job"]["block"]==b).unwrap();let ratios=(0..3).map(|b|get(b,true)["mean_ms"].as_f64().unwrap()/get(b,false)["mean_ms"].as_f64().unwrap()).collect::<Vec<_>>();let median=med(ratios.clone());let wins=ratios.iter().filter(|&&v|v<1.).count();let cpu=med((0..3).map(|b|get(b,true)["cpu_ms"].as_f64().unwrap()/get(b,false)["cpu_ms"].as_f64().unwrap()).collect());let peak=|l32:bool|(0..3).map(|b|get(b,l32)["peak_rss_mib"].as_f64().unwrap()).fold(0.,f64::max);let guard=cpu<=1.02&&peak(true)<=(peak(false)*1.1).max(peak(false)+8.);let getmode=|l32:bool|json!({"mean_ms":med((0..3).map(|b|get(b,l32)["mean_ms"].as_f64().unwrap()).collect()),"cpu_ms":med((0..3).map(|b|get(b,l32)["cpu_ms"].as_f64().unwrap()).collect()),"peak_rss_mib":peak(l32)});if !trace{sdk_selected=ready&&median<1.&&wins>=2&&guard;}comparisons.push(json!({"trace":trace,"L16":getmode(false),"L32":getmode(true),"paired_L32_over_L16":ratios,"median_ratio":median,"wins":wins,"CPU_ratio":cpu,"guards":guard}));}}
let result=json!({"pass":true,"source214_retained":178,"source214_layout_modified":4,"original_prepare_unchanged":true,"processes":processes,"layout_records":count,"layout_counts":layout_counts,"Boolean_disabled":true,"equal_capacity_padding_bytes":56,"mechanism_selection":mechanism,"SDK_directional_selection_only":sdk_selected,"comparisons":comparisons,"adopted":false,"no_accepted194_comparison":true});let p=r.join(if smoke_only{"layout-smoke.json"}else{"layout-result.json"});assert!(!p.exists());fs::write(p,serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("LayoutPASS {count}records/{processes}processes;mechanismselected={mechanism},SDKdirectionalselected={sdk_selected}");}
